// Standard 12 oz can: geometry, lid, rims and shading copied from the Good cola cans
// (colas.mjs). The left highlight and the speckle are drawn under the label here: over
// white-on-black artwork they leave ghost marks.
const CAN='M61 41Q100 32 139 41L145 58V220Q145 233 100 233T55 220V58Z';
function can(slug,title,label,color,defs=''){
  return wrap(slug,title,`${shadow(58)}<path d="${CAN}" fill="${color}"/>
<g clip-path="${ref('bodyclip')}">
<path d="M65 62V213" fill="none" stroke="#fff" stroke-opacity=".1" stroke-width="3.1"/>
<path d="M138 62V213" fill="none" stroke="#fff" stroke-opacity=".07" stroke-width="1.3"/>
${Array.from({length:19},(_,i)=>`<ellipse cx="${65+i*29%69}" cy="${67+i*43%145}" rx="${i%4?.6:1.05}" ry="${i%4?1:1.6}" fill="#fff" opacity=".07"/>`).join('')}
${label}
<path d="${CAN}" fill="${ref('shade')}" opacity=".85"/>
</g>
<ellipse cx="100" cy="41" rx="39" ry="8" fill="${ref('metal')}" stroke="#9ca7a4" stroke-width="1.1"/>
<ellipse cx="100" cy="41" rx="34" ry="5.5" fill="none" stroke="#8d9892" stroke-width=".8"/>
<ellipse cx="105" cy="42" rx="8" ry="3.5" fill="#657169"/>
<path d="M93 39h10q6 0 5 4t-8 3h-6q-6-1-1-7" fill="none" stroke="#e6e8de" stroke-width="2.4"/>
<path d="M58 226q42 12 84 0" fill="none" stroke="${ref('metal')}" stroke-width="4"/>
<path d="M61 230q39 7 78 0" fill="none" stroke="#fff" stroke-opacity=".55" stroke-width="1"/>`,
`<clipPath id="__ID__bodyclip"><path d="${CAN}"/></clipPath>${defs}`);
}

function jackAndCoke(){
  const slug='jack-daniels-and-coke',title="Jack Daniel's & Coca-Cola";
  // One uniform scale for the whole label: the packshot's 606 px can width onto the 90-unit can.
  const k=.148,ty=8.7,white='#f7f6f2',red='#e00a12';
  const place=(d,y0,fill)=>`<path transform="translate(100 ${+(ty+y0*k).toFixed(2)}) scale(${k})" fill="${fill}" fill-rule="evenodd" d="${d}"/>`;
  const serif='style="font-family:Georgia,serif;font-weight:bold"';
  const label=`${place(JD_LOCKUP,JD_Y0,white)}
${text(100.1,138.7,'TENNESSEE WHISKEY',3.55,white,`${serif} textLength="59.4" lengthAdjust="spacing"`)}
${text(100.1,144.1,'MIXED WITH',2.5,white,'font-weight="bold" textLength="26.3" lengthAdjust="spacing"')}
${place(COCA_COLA,COCA_Y0,red)}
${text(77.05,213.1,'355 mL',7.6,white,'textLength="15.9" lengthAdjust="spacingAndGlyphs"')}
${text(97.25,213.8,'7.0%',10.1,white,'style="font-family:Times New Roman,serif;font-weight:bold" textLength="19.1" lengthAdjust="spacingAndGlyphs"')}
${text(119.2,213.1,'ALC./VOL.',5.6,white,'textLength="18.4" lengthAdjust="spacingAndGlyphs"')}`;
  const svg=can(slug,title,label,ref('black'),`<linearGradient id="__ID__black"><stop stop-color="#343033"/><stop offset=".07" stop-color="#121011"/><stop offset=".24" stop-color="#191617"/><stop offset=".5" stop-color="#070506"/><stop offset=".9" stop-color="#0b090a"/><stop offset="1" stop-color="#363336"/></linearGradient>`);
  return {
    slug,family:'jack-daniels-cocktail-can',
    packageChoice:'US 355 mL (12 fl oz) Jack Daniel’s & Coca-Cola ready-to-drink can, 7% ALC./VOL.: the standard black can shown on the Jack Daniel’s product page.',
    references:[{pageUrl:'https://www.jackdaniels.com/en-us/whiskey/jack-daniels-coca-cola',imageUrl:'https://cms.jackdaniels.com/sites/default/files/2025-04/Jack%20Daniel%27s%20Coca%20Cola%20-%20with%20reflection_0.png',inspectedAt:date,visuallyInspected:true,observations:'Manufacturer front render of a standard 12 oz can with a reflection beneath it. Black can; JACK DANIEL’S arched in white capitals; the Old No. 7 Brand oval cartouche with filigree; TENNESSEE WHISKEY and MIXED WITH in small spaced white capitals; the Coca-Cola script in red; 355 mL 7.0% ALC./VOL. in white at the foot.'}],
    uncertainty:'The Jack Daniel’s lockup and the Coca-Cola script are path constants vectorised from the packshot (module header); the filigree inside the cartouche is simplified. The reflection under the can is left out. These notes were written at review from the reference and the render; the agent that drew the icon was interrupted before writing them.',
    status:'needs-review',svg,
  };
}


// ---------------------------------------------------------------------------------------
// Glass longneck bottles. Rendering copied from the Good beer bottles (`bottle()` in
// beer-expansion.mjs): glass gradient, clip, `glass` and `shade` overlays, the droplet
// speckle (drawn under the paper labels here, so it only shows on glass), a left specular and a faint right one, crown cap, base glint, shadow(47).
// Same height (cap at y=24, base at y=235) as those bottles. Each bottle supplies its own
// silhouette, measured off its packshot, and specular paths that follow it.
const drops=(x,y,w,h,n=18)=>Array.from({length:n},(_,i)=>`<ellipse cx="${x+(i*19)%w}" cy="${y+(i*31)%h}" rx="${i%3===0?1.2:.7}" ry="${i%3===0?1.8:1}" fill="#fff" opacity=".28"/>`).join('');
const CROWN='M87.5 24q12.5-4 25 0l2 6-3 2-3-1-3 1-3-1-3 1-3-1-3 1-3-1-3 1-2-2Z';
function bottle(slug,title,label,{shape,light,glass,dark,closure,spec,inside='',defs=''}){
  return wrap(slug,title,`${shadow(47)}<path d="${shape}" fill="${ref('liquid')}" stroke="${dark}" stroke-width=".65"/>
<g clip-path="${ref('bottleclip')}">${inside}${drops(72,67,56,156,25)}${label}<path d="${shape}" fill="${ref('glass')}" opacity=".4"/><path d="${shape}" fill="${ref('shade')}" opacity=".65"/>
<path d="${spec[0]}" fill="none" stroke="#fff9df" stroke-opacity=".24" stroke-width="2.8"/><path d="${spec[1]}" fill="none" stroke="#fff9df" stroke-opacity=".18" stroke-width="1.1"/></g>
${closure}<path d="M72 227q28 7 56 0" fill="none" stroke="#fff7d5" stroke-opacity=".3" stroke-width="1.2"/>`,
`<clipPath id="__ID__bottleclip"><path d="${shape}"/></clipPath><linearGradient id="__ID__liquid"><stop stop-color="${dark}"/><stop offset=".25" stop-color="${light}"/><stop offset=".58" stop-color="${glass}"/><stop offset="1" stop-color="${dark}"/></linearGradient>${defs}`);
}
// Traced constants are integers in 1/20 unit (keeps the exported file small).
const traced=(d,c,extra='')=>`<path transform="scale(.05)" d="${d}" fill="${c}" fill-rule="evenodd"${extra}/>`;
// Foil-paper fleck for the metallic gold labels: fixed pseudo-random dots (integer LCG).
function fleck(x0,y0,w,h,n,seed,light,dark){
  // x0,y0,w,h are whole units; every coordinate is an integer number of tenths.
  let v=seed;const d=['',''];
  const next=()=>(v=(v*73+41)%9973);
  for(let i=0;i<n;i++){const x=x0*10+next()%(w*10),y=y0*10+next()%(h*10),l=3+next()%5;d[i%2]+=`M${x/10} ${y/10}h${l/10}`;}
  return `<path d="${d[1]}" stroke="${light}" stroke-width=".7" stroke-linecap="round" opacity=".55"/><path d="${d[0]}" stroke="${dark}" stroke-width=".6" stroke-linecap="round" opacity=".32"/>`;
}

// Dos Equis Lager Especial, 12 fl oz green longneck.
// XX_WORD (DOS EQUIS), XX_HEAD (the Moctezuma head in the medallion) and XX_SCRIPT (Lager
// Especial) were traced from the flat artwork printed on the six-pack carrier in the same
// retailer image as the bottle (perspective removed using the medallion's four corners).
// The XX, the medallion and the label's four triangles are constructed: each X is four
// chevrons (measured on the bottle label: stripe 40, slope .788, centres 95 either side
// of the axis, in packshot pixels). Everything was then projected onto the bottle's
